function [s, ix, med, top3, ws, wix] = sorted(v, w)
%SORTED  The toolbox sort: ascending, equal values in their order; a median, the three largest, whole numbers with ties.
%   v: real[m][7] (passed in m)
%   w: int[5] (passed a whole number)
%   returns s: real[m][7] (passed in m)
%   returns ix: int[7] (passed a whole number)
%   returns med: real[m] (passed in m)
%   returns top3: int[3] (passed a whole number)
%   returns ws: int[5] (passed a whole number)
%   returns wix: int[5] (passed a whole number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    s = zeros(7, 1);
    ix = zeros(7, 1);
    med = 0;
    top3 = zeros(3, 1);
    ws = zeros(5, 1);
    wix = zeros(5, 1);
    s = asils.pc.sort_(v);
    ix = asils.pc.argsort_(v);
    med = s(4);
    big = asils.pc.argsort_((-(v)));
    k = ((0):((3) - 1)).';
    top3((k) + 1) = reshape(big((k) + 1), [], 1);
    ws = asils.pc.sort_(w);
    wix = asils.pc.argsort_(w);
end
